import torch
from tests.test_engine import make_engine, prompts, run_alone, CFG
from pagedserve.sched.request import SamplingParams


def test_chunked_prefix_preemption_matches_alone():
    ps = prompts(8, seed=3)
    sp = SamplingParams.greedy(14, ignore_eos=True)
    eng = make_engine('paged_torch', num_blocks=14, block_size=4, max_batched=7,
                      enable_chunked_prefill=True, enable_prefix_caching=True)
    for i, p in enumerate(ps):
        eng.add_request(str(i), p, sp)
    res = {}
    n = 0
    while eng.has_unfinished_requests():
        for o in eng.step():
            if o.finished:
                res[o.request_id] = o.output_token_ids
        n += 1
        assert n < 2000
    assert sum(s.num_preempted for s in eng.stats) > 0
    for i, p in enumerate(ps):
        assert res[str(i)] == run_alone('paged_torch', p, 14)
